function evalGrid(p,g,lb,mul){let tot=0;const wins=[];LINES.forEach((ln,li)=>{const s=ln.map((row,r)=>g[r][row]);let base=-1;for(const x of s){if(x<8){base=x;break}if(x==9)break}if(base<0)return;let n=0;for(const x of s){if(x==base||x==8)n++;else break}if(n>=2&&p.pt[base][n-2]>0){const m=p.pt[base][n-2]*p.k*mul,pay=lb*m;tot+=pay;wins.push({l:li,s:base,n,pay})}});return{tot,wins}}
