// ---- v13 UPDATE MAIL: when VERSION changes, every player gets this in their mailbox once.
// To announce a future update: bump VERSION and replace CHANGELOG (player-facing features only, no admin commands).
const VERSION=15,CHANGELOG={title:'📣 High Flip update: Promo Codes & the Halloween theme',body:'What\'s new:\n• 🎟️ Codes: a new Codes tab at the top of the screen. Got a promo code? Type it in to claim rewards like money or exclusive themes. Keep an eye out for codes in chat and announcements.\n• 🎃 Halloween theme: a brand new EXCLUSIVE theme with a glowing moon, flying bats, floating ghosts and a dangling spider. Check the Themes tab (the other themes are $2T each, this exclusive one is $10T).\n• ⏱️ Big dramatic on-screen countdowns can now happen for special events.'};
function sendChangelog(){if(DB.ver===VERSION)return;DB.ver=VERSION;const ts=Date.now();for(const u of Object.values(DB.users)){u.mail=u.mail||[];u.mail.unshift({id:rid(4),ts,r:0,from:'System',title:CHANGELOG.title,body:CHANGELOG.body});if(u.mail.length>25)u.mail.length=25}save();for(const u of Object.values(DB.users)){if(cl.has(u.id)){push(u);to(u,'mailnew',{title:CHANGELOG.title,from:'System'})}}}


// ---- v15 CODES, THEME LOCKS, COUNTDOWN
let CD=null;const cdOf=()=>CD&&CD.end>Date.now()?CD:null;
function seedCodes(){DB.codes=DB.codes||{};DB.thlock=DB.thlock||{};if(!DB.codes.HALLOWEEN2026){DB.codes.HALLOWEEN2026={code:'HALLOWEEN2026',amt:0,theme:'halloween',max:0,uses:0,off:false,ts:Date.now(),by:'System'}}save()}
Object.assign(G,{
'code/redeem'(u,b){const n=Date.now();DB.codes=DB.codes||{};DB.thlock=DB.thlock||{};if(u.cblock>n)throw'Too many wrong codes. Try again in a few minutes.';const code=String(b.code||'').trim().toUpperCase().replace(/[^A-Z0-9_-]/g,''),c=DB.codes[code];
if(!c){u.cf=(u.cf||0)+1;if(u.cf>=8){u.cblock=n+300000;u.cf=0}save();throw'That code is not valid'}
if(c.off)throw'That code has been disabled';u.rc=u.rc||[];if(u.rc.includes(code))throw'You already redeemed that code';if(c.max&&c.uses>=c.max)throw'That code has run out of uses';
if(c.theme){if(DB.thlock[c.theme])throw'🔒 That reward is locked right now';if((u.th||[]).includes(c.theme)&&!(c.amt>0))throw'You already own the '+THEMES[c.theme].name+' theme'}
u.cf=0;u.rc.push(code);c.uses=(c.uses||0)+1;const got=[];if(c.amt>0){u.bal=Math.min(MAXB,r2(u.bal+c.amt));got.push(fmM(c.amt))}
if(c.theme){u.th=u.th||[];if(!u.th.includes(c.theme)){u.th.push(c.theme);got.push('the '+THEMES[c.theme].name+' theme')}}
save();push(u);return{reward:got.join(' + ')||'a surprise',theme:c.theme||'',amt:c.amt||0}}
});
// ---- v14 CHAT RAIN + PLAYTIME
const fmM=n=>{n=+n;const U=[[1e15,'Q'],[1e12,'T'],[1e9,'B'],[1e6,'M'],[1e3,'K']];for(const[v,l]of U)if(n>=v)return '$'+(Math.round(n/v*100)/100)+l;return '$'+Math.round(n*100)/100},rviewR=(R,u)=>R?{id:R.id,pot:R.pot,start:R.start,end:R.end,n:Object.keys(R.j).length,by:R.by,auto:!!R.auto,j:!!(u&&R.j[u.id])}:null;
function rainBc(){const R=DB.rain;bc('rain',R?rviewR(R):null)}
function rainStart(a,sec,by,auto){const n=Date.now();let R=DB.rain;if(R){R.pot=r2(R.pot+a);R.end=Math.max(R.end,n+sec*1000)}else R=DB.rain={id:rid(4),pot:r2(a),start:n,end:n+sec*1000,by,auto:!!auto,j:{}};save();chatAdd({t:'ann',x:'🌧️ A rain of '+fmM(a)+' '+(R.j&&Object.keys(R.j).length||!auto?'was added':'has started')+'! Press JOIN above the chat to share it.'});rainBc()}
function rainEnd(){const R=DB.rain;if(!R)return;DB.rain=null;const ids=Object.keys(R.j).filter(id=>DB.users[id]);if(!ids.length)chatAdd({t:'sys',x:'🌧️ The rain ended and nobody joined, so the '+fmM(R.pot)+' pot dried up.'});else{const each=r2(R.pot/ids.length);for(const id of ids){const x=DB.users[id];x.bal=Math.min(MAXB,r2(x.bal+each));push(x);to(x,'note',{x:'🌧️ You got '+fmM(each)+' from the rain!'})}chatAdd({t:'sys',x:'🌧️ The rain ended: '+ids.length+' player'+(ids.length>1?'s':'')+' got '+fmM(each)+' each.'})}save();rainBc()}
Object.assign(G,{
'rain/join'(u){const R=DB.rain;if(!R||R.end<=Date.now())throw'There is no rain right now';if(R.j[u.id])throw'You already joined this rain';R.j[u.id]=1;save();to(u,'rain',rviewR(R,u));rainBc();return{}},
'rain/tip'(u,b){const R=DB.rain;if(!R||R.end<=Date.now())throw'There is no rain to tip right now';const a=take(u,b.amt);if(a<1){u.bal=r2(u.bal+a);throw'Tip at least $1'}R.pot=r2(R.pot+a);save();push(u);chatAdd({t:'sys',x:'💧 '+u.name+' tipped '+fmM(a)+' into the rain! Pot: '+fmM(R.pot)});rainBc();return{}}
});
